#include <chrono>
#include <iomanip>
#include <iostream>
#include <cstdint>

#include "Halide.h"

// include common definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (e.g. N, DATA_TYPE)
#include "nussinov.hpp"

using num_t  = DATA_TYPE;   // type used for table entries
using base_t = uint8_t;     // type used for RNA bases (0..3)

using namespace Halide;

// Initialize seq and table as in the original C code.
static void init_array(int n,
                       Halide::Buffer<base_t, 1> seq,
                       Halide::Buffer<num_t, 2> table) {
    Var i("i"), j("j");

    Func init_seq("init_seq"), init_table("init_table");

    // base is AGCT/0..3
    init_seq(i) = cast<base_t>((i + 1) % 4);

    // table[i][j] = 0 for all i,j
    // Remember: C uses table[i][j]; we map that to table(j, i).
    init_table(j, i) = cast<num_t>(0);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    // seq[i]      -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    seq_param.set(seq);
    table_param.set(table);

    // Scalar parameters for problem size and current diagonal length.
    // N_param stays constant; len_param varies per outer iteration.
    Param<int> N_param("N");
    Param<int> len_param("len");
    N_param.set(n);

    // ------------------------------------------------------------------
    // Halide pipeline: compute one anti-diagonal ("wavefront") at a time
    // ------------------------------------------------------------------
    //
    // We re-express the DP in terms of the span d = j - i. For a fixed
    // d, all cells (i, j = i + d) are independent, because every term in
    // the recurrence for table[i][j] only uses entries with strictly
    // smaller span:
    //
    //   table[i, j-1], table[i+1, j]       -> span d-1
    //   table[i+1, j-1]                    -> span d-2
    //   table[i, k], table[k+1, j], i<k<j  -> spans < d
    //
    // We drive d (our len_param) from the host sequentially, and for a
    // fixed d we let Halide compute the entire diagonal in parallel.
    //
    // The Func `diag(p)` computes table[i][j] for i = p and j = p + len.
    // It reads from the current `table_param` (which already contains
    // all smaller diagonals) and from `seq_param`, and produces a 1-D
    // array of length (n - len). The host then writes this diagonal
    // back into `table`.
    //

    Var p("p");               // index along current diagonal: i = p
    RDom r(0, N_param - 1, "r"); // reduction index for split term (k)

    Func diag("diag");

    {
        Expr i = p;                  // row index i
        Expr j = i + len_param;      // column index j = i + len

        // ------------------------------
        // Base candidates (no splitting)
        // ------------------------------
        //
        // Original C:
        //   best = table[i][j];
        //   best = max(best, table[i][j-1]);
        //   best = max(best, table[i+1][j]);
        //
        // table[i][j] is initialized to 0 and never used elsewhere
        // before being written, so we can start from:
        //   best = max(table[i][j-1], table[i+1][j]).
        //
        // Mapping to Halide indices:
        //   table[i][j-1] -> table_param(j-1, i)
        //   table[i+1][j] -> table_param(j,   i+1)

        Expr left  = table_param(j - 1, i);
        Expr down  = table_param(j,     i + 1);
        Expr best0 = max(left, down);

        // ------------------------------
        // Diagonal / pairing term
        // ------------------------------
        //
        // Original C:
        //   if (i < j-1)
        //     best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
        //   else
        //     best = max(best, table[i+1][j-1]);
        //
        // match(b1,b2) = ((b1 + b2) == 3 ? 1 : 0)
        //
        // We encode this as:
        //   pair_bonus = (i < j-1 ? match : 0)
        //   best = max(best0, table[i+1][j-1] + pair_bonus)

        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));
        Expr match_val  = select(b1 + b2 == 3, 1, 0);
        Expr pair_bonus = select(i < j - 1, match_val, 0);

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate =
            table_param(j - 1, i + 1) + cast<num_t>(pair_bonus);

        Expr best = max(best0, diag_candidate);

        // Pure definition: best without the split term.
        diag(p) = best;

        // ------------------------------
        // Split term: max over k∈(i, j)
        // ------------------------------
        //
        // Original C:
        //   for (k = i+1; k < j; k++)
        //     best = max(best, table[i][k] + table[k+1][j]);
        //
        // In our storage mapping:
        //   table[i][k]     -> table_param(k,   i)
        //   table[k+1][j]   -> table_param(j,   k+1)
        //
        // We can't make the RDom extent depend on `i` and `j` directly,
        // so we iterate k over a safe global range [0, N-2] and mask
        // out values outside (i+1, j-1) with a `select`. Because all
        // table entries are non-negative, using 0 as the masked value
        // is equivalent to not considering that k.
        //
        // For each diagonal cell (i,j), this does O(N) work; the DP as
        // a whole is still O(N^3) as in the original algorithm.

        Expr k      = r.x;
        Expr in_rng = (k > i) && (k < j);

        // Candidate is non-zero only when i < k < j.
        Expr split_candidate =
            select(in_rng,
                   table_param(k, i) + table_param(j, k + 1),
                   cast<num_t>(0));

        diag(p) = max(diag(p), split_candidate);
    }

    // ------------------------------
    // Schedule for `diag`
    // ------------------------------
    //
    // For a fixed diagonal length `len_param`, all p (i-indices) are
    // independent and can be computed in parallel. Within each p, we
    // have a reduction over r.x (the split index k). We:
    //
    //   - tile and parallelize over p,
    //   - vectorize the inner p-loop,
    //   - unroll the inner part of the k-reduction.
    //
    Var po("po"), pi("pi");
    RVar ro("ro"), ri("ri");

    diag
        .compute_root()
        .split(p, po, pi, 64)   // tiles of 64 cells along the diagonal
        .parallel(po)           // different tiles in parallel
        .vectorize(pi, 8);      // 8-wide SIMD across independent cells

    diag.update()
        .split(p, po, pi, 64)
        .parallel(po)
        .vectorize(pi, 8)
        .split(r.x, ro, ri, 8)  // small tiles in k
        .unroll(ri);            // unroll inner k-loop to expose ILP

    // JIT-compile the per-diagonal pipeline once.
    Target target = get_host_target();
    diag.compile_jit(target);

    // Buffer to hold one diagonal; size n is enough for all lengths.
    Halide::Buffer<num_t, 1> diag_buf(n);

    // Time the DP kernel (the length loop + Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Dynamic program in increasing span d = j - i (wavefront order).
    // This preserves all dependencies and lets Halide parallelize and
    // vectorize across i for each fixed d.
    for (int len = 1; len < n; ++len) {
        len_param.set(len);

        int diag_len = n - len;           // number of cells on this diagonal

        // Create a lightweight view of the first `diag_len` elements
        // of diag_buf, so we can reuse the same underlying storage.
        Halide::Buffer<num_t, 1> diag_slice =
            diag_buf.cropped(0, diag_len);

        // Compute this diagonal with Halide.
        diag.realize(diag_slice);

        // Write the diagonal back into `table`:
        //   i = p = 0 .. diag_len-1
        //   j = i + len
        for (int i = 0; i < diag_len; ++i) {
            int j = i + len;
            // C: table[i][j]  -> Halide: table(j, i)
            table(j, i) = diag_slice(i);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        int t = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if (t % 20 == 0) {
                    std::cerr << '\n';
                }
                std::cerr << table(j, i) << ' ';
                ++t;
            }
        }
        std::cerr << '\n';
    }

    // Print kernel execution time (in seconds, to 6 decimal places).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
