int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    // seq[i]      -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2>  table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter: current subsequence length d = j - i (wavefront index)
    Param<int> d_param("d");

    // Bind the buffers once; we mutate 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // ------------------------------------------------------------------
    // Halide pipeline: compute one anti-diagonal (fixed d) of the DP table
    //
    // We use the standard Nussinov recurrence, but evaluate it for all
    // cells (i, j = i + d) of a single diagonal in one Halide call.
    //
    // DP dependencies:
    //   table[i][j] uses only entries with strictly smaller (j - i),
    //   so computing diagonals in increasing d is a valid topological
    //   order, and all cells on the same diagonal are independent.
    // ------------------------------------------------------------------
    Var  i("i");
    Func diag("diag");

    {
        Expr d = d_param;       // current diagonal (subsequence length)
        Expr j = i + d;         // column index j = i + d

        // Start from the "left" and "down" candidates:
        //
        // best = max( table[i][j-1], table[i+1][j] )
        //
        // Mapping to table_param(j, i):
        //   table[i][j-1] -> table_param(j-1, i)
        //   table[i+1][j] -> table_param(j,   i+1)
        Expr best = table_param(j - 1, i);
        best      = max(best, table_param(j, i + 1));

        // Diagonal / pairing term:
        //
        //   if (i < j-1)
        //       best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
        //   else
        //       best = max(best, table[i+1][j-1]);
        //
        // but table[i+1][j-1] is always on a strictly smaller diagonal and
        // initialized to 0 below the main diagonal, so for d == 1 the term
        // is effectively 0 in either branch. We can therefore express it as:
        //
        //   best = max(best, table[i+1][j-1] + (i < j-1 ? match : 0));
        //
        // match(seq[i], seq[j]) = 1 if seq[i] + seq[j] == 3, else 0.
        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));
        Expr match_val  = select(b1 + b2 == 3, 1, 0);
        Expr match_term = select(i < j - 1,
                                 cast<num_t>(match_val),
                                 cast<num_t>(0));

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate = table_param(j - 1, i + 1) + match_term;
        best = max(best, diag_candidate);

        // Split term:
        //
        //   for (k = i+1; k < j; k++)
        //       best = max(best, table[i][k] + table[k+1][j]);
        //
        // In terms of indices and table_param:
        //   table[i][k]     -> table_param(k,   i)
        //   table[k+1][j]   -> table_param(j,   k+1)
        //
        // This is a reduction over k in [i+1, j-1], written with an RDom
        // whose min and extent depend on the pure variable i and the
        // parameter d. This is legal in Halide and gives us a clean
        // per-cell reduction inside a per-diagonal Func.
        Expr extent = j - (i + 1);   // == d - 1; number of valid k
        RDom r(i + 1, extent, "r");

        // Pure definition: initial best value for this (i, j) cell.
        diag(i) = best;

        // Reduction update: take the maximum over all valid k.
        diag(i) = max(diag(i),
                      table_param(r.x, i) + table_param(j, r.x + 1));
    }

    // ------------------------------------------------------------------
    // Schedule for diag:
    //   - Compute at root (one realization per diagonal).
    //   - Parallelize and vectorize across i (cells of a diagonal),
    //     which are all independent for a fixed d.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    diag.compute_root();
    if (vec_width > 1) {
        diag.vectorize(i, vec_width);
    }
    diag.parallel(i);

    // JIT-compile the per-diagonal pipeline once.
    diag.compile_jit(target);

    // Temporary storage to hold one diagonal worth of results.
    // We allocate the maximum possible length (n), then for each
    // diagonal create a lightweight view with the appropriate extent.
    Halide::Buffer<num_t, 1> diag_storage(n);

    // Time the DP kernel (all diagonals plus Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Original kernel order (conceptually):
    //
    // for (i = N-1; i >= 0; i--)
    //   for (j = i+1; j < N; j++)
    //     ... updates to table[i][j] ...
    //
    // is equivalent (given the dependence pattern) to a wavefront / diagonal
    // traversal in increasing subsequence length d = j - i:
    //
    //   for (d = 1; d < N; d++)
    //     for (i = 0; i + d < N; i++) {
    //       j = i + d;
    //       ... recurrence for table[i][j] ...
    //     }
    //
    // We implement exactly this order on the host, but each diagonal d is
    // computed with a single Halide realization of 'diag' that covers all i.
    for (int d = 1; d < n; ++d) {
        d_param.set(d);

        // Number of (i, j=i+d) cells on this diagonal
        int diag_len = n - d;

        // Create a view onto the first diag_len elements of diag_storage.
        Halide::Buffer<num_t, 1> diag_buf(diag_storage.data(), diag_len);

        // Compute all table[i][j] on this diagonal into diag_buf(i).
        diag.realize(diag_buf);

        // Write back into the DP table buffer.
        for (int i_idx = 0; i_idx < diag_len; ++i_idx) {
            int j = i_idx + d;
            // C: table[i_idx][j]   -> Halide: table(j, i_idx)
            table(j, i_idx) = diag_buf(i_idx);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

