    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    // seq[i]      -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major by default)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2>  table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // -------------------------------------------------------------------------
    // Halide representation of the DP state and inputs
    // -------------------------------------------------------------------------

    // ImageParams expose the current state of 'seq' and 'table' to Halide.
    // We bind them once; we mutate 'table' in-place on the host, and Halide
    // will always read the up-to-date values from it.
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    seq_param.set(seq);
    table_param.set(table);

    // Scalar parameter: current diagonal length d = j - i (1 .. n-1).
    // We will sweep d from 1 to n-1 on the host (wavefront traversal),
    // while Halide computes all cells on a given diagonal in one call.
    Param<int> d_param("d_param");

    // -------------------------------------------------------------------------
    // Halide Func: compute all cells on a fixed anti-diagonal
    //
    // For a fixed diagonal length d, all cells (i, j = i + d) are independent,
    // and every dependency of table[i][j] lies strictly on a smaller diagonal.
    //
    // We define a 1D Func 'band' over the row index i, and compute:
    //
    //   j = i + d_param
    //   best = max over:
    //     table[i][j-1]                (left)
    //     table[i+1][j]                (down)
    //     table[i+1][j-1] + match(i,j) (pairing, if i < j-1)
    //     table[i][k] + table[k+1][j]  (split, for k in (i+1 .. j-1))
    //
    // with the same recurrence as the original code.
    //
    // Index mapping:
    //   C code:   table[i][j]
    //   Halide:   table_param(j, i)
    // -------------------------------------------------------------------------
    Var i("i");          // row index in DP table
    Func band("band");   // one diagonal's worth of cells

    // RDom for the split term. It will cover k in [i+1, j-1]. We express this
    // as an offset from i: r.x in [1, d_param-1], and set k = i + r.x.
    RDom r(1, d_param - 1, "r"); // extent is zero when d_param == 1 (no splits)

    {
        Expr d = d_param;
        Expr j = i + d;

        // --- Base candidates ---

        // table[i][j-1] -> table_param(j-1, i)
        Expr best = table_param(j - 1, i);

        // table[i+1][j] -> table_param(j, i+1)
        best = max(best, table_param(j, i + 1));

        // Diagonal / pairing term:
        //
        // Original C:
        //   if (j-1 >= 0 && i+1 < N) {
        //     if (i < j-1)
        //       table[i][j] = max(table[i][j],
        //                          table[i+1][j-1] + match(seq[i], seq[j]));
        //     else
        //       table[i][j] = max(table[i][j], table[i+1][j-1]);
        //   }
        //
        // In the DP region (i < j, d >= 1), the outer condition always holds.
        // Only (i < j-1) matters: it prevents pairing adjacent bases.
        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));
        // match(seq[i],seq[j]) = 1 if b1 + b2 == 3, else 0
        Expr match_val = select(b1 + b2 == 3, 1, 0);

        Expr match_term = select(i < j - 1,
                                 cast<num_t>(match_val),
                                 cast<num_t>(0));

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate = table_param(j - 1, i + 1) + match_term;
        best = max(best, diag_candidate);

        // --- Initialize band(i) with the best non-split candidate ---
        band(i) = best;

        // --- Split term: for k in (i+1 .. j-1) ---
        //
        // C code:
        //   for (k = i+1; k < j; k++)
        //     table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
        //
        // We use r.x in [1, d_param-1] and set k = i + r.x.
        Expr k = i + r.x;
        band(i) = max(band(i),
                      table_param(k, i)       // table[i][k]   -> table_param(k, i)
                      + table_param(j, k + 1) // table[k+1][j] -> table_param(j, k+1)
                     );
    }

    // -------------------------------------------------------------------------
    // Schedule for 'band'
    //
    // We rely on host-driven iteration over diagonals (d_param), and let
    // Halide exploit parallelism and vectorization across 'i' for each
    // diagonal, as well as optimize within each split-reduction.
    // -------------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile 'i' to improve cache locality and to get coarse-grained tasks
    // for parallel execution, then vectorize within each tile.
    Var io("io"), ii("ii");
    band.compute_root()
        .split(i, io, ii, 64)    // tile size along i; tunable
        .parallel(io)            // parallelize tiles of i
        .vectorize(ii, vec_width);

    // Apply the same tiling and vectorization pattern to the reduction update.
    band.update()
        .split(i, io, ii, 64)
        .parallel(io)
        .vectorize(ii, vec_width);
    // We leave the RDom loop over r.x scalar but fully optimized by -O3.

    // JIT-compile the diagonal kernel once.
    band.compile_jit(target);

    // Temporary 1D buffer to hold a single diagonal's results.
    // We reuse this buffer for all diagonals; only a prefix is used each time.
    Halide::Buffer<num_t, 1> band_result(n);

    // -------------------------------------------------------------------------
    // Time the dynamic-programming kernel: full DP over all i,j.
    // We now use a wavefront (anti-diagonal) order:
    //
    //   for (d = 1; d < n; d++)
    //     for (i = 0; i + d < n; i++) {
    //       j = i + d;
    //       table[i][j] = recurrence(...)
    //     }
    //
    // This preserves all dependencies (each table[i][j] only uses entries
    // with strictly smaller j - i) and exposes parallelism across i.
    //
    // The order differs from the original i-descending/j-ascending loops,
    // but the final DP table is mathematically identical.
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int d = 1; d < n; ++d) {
        d_param.set(d);

        const int diag_len = n - d;  // number of (i,j) pairs with j = i + d

        // Realize band(i) for i in [0, diag_len).
        // We realize into a cropped view of 'band_result' to avoid reallocation.
        Halide::Buffer<num_t> diag_view = band_result.cropped(0, 0, diag_len);
        band.realize(diag_view);

        // Copy the diagonal results back into the DP table:
        //   table[i][j]  (C)  ->  table(j, i) (Halide)
        for (int i_row = 0; i_row < diag_len; ++i_row) {
            int j_col = i_row + d;
            table(j_col, i_row) = band_result(i_row);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        int t = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if (t % 20 == 0) {
                    std::cerr << '\n';
                }
                // C's table[i][j] == Halide's table(j, i)
                std::cerr << table(j, i) << ' ';
                ++t;
            }
        }
        std::cerr << '\n';
    }

    // Print kernel execution time (in seconds, to 6 decimal places).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
