    // Buffers:
    // seq[i]     -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams expose the current state of the buffers to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter: current subsequence length L = j - i
    Param<int> len_param("len");

    // Bind the buffers once; we will update 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // --------------------------------------------------------------------
    // Optimized Halide pipeline: compute an entire anti-diagonal at once.
    //
    // For a fixed subsequence length L = len_param, all cells (i, j = i+L)
    // satisfy j - i = L and are mutually independent given that all
    // shorter lengths (< L) have been computed. We exploit this by
    // defining a 1D Func 'diag(i)' that computes table[i][i+L] for a
    // range of i, and then drive a wavefront traversal over L on the host.
    //
    // This replaces the original per-cell Halide kernel with a much
    // larger-granularity kernel (one per diagonal), enabling parallelism
    // and vectorization across i.
    // --------------------------------------------------------------------
    Var i("i");
    Func diag("diag");

    {
        Expr L = len_param;
        Expr ii = cast<int32_t>(i);
        Expr jj = ii + L;  // j = i + L

        // Current best value for table[i][j]. In the original C code
        // table[i][j] is initialized to 0 before the DP, so we can
        // start from 0 rather than loading it.
        Expr best = cast<num_t>(0);

        // left: table[i][j-1] -> table_param(j-1, i)
        best = max(best, table_param(jj - 1, ii));

        // down: table[i+1][j] -> table_param(j, i+1)
        best = max(best, table_param(jj, ii + 1));

        // diagonal / pairing term:
        //
        // match(seq[i], seq[j]) = 1 if bases are complementary, else 0.
        // PolyBench encoding: (b1 + b2 == 3) ? 1 : 0
        Expr b1 = cast<int32_t>(seq_param(ii));
        Expr b2 = cast<int32_t>(seq_param(jj));
        Expr match_val = select(b1 + b2 == 3, 1, 0);

        // Only allow bonding when i < j-1; otherwise, the bonus is 0.
        Expr pair_bonus = select(ii < jj - 1, match_val, 0);

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate =
            table_param(jj - 1, ii + 1) + cast<num_t>(pair_bonus);
        best = max(best, diag_candidate);

        // Pure definition: initial best for this (i, j=i+L)
        diag(i) = best;

        // Split term:
        //
        // for (k = i+1; k < j; k++)
        //   best = max(best, table[i][k] + table[k+1][j]);
        //
        // Expressed as a reduction over k. We use a relative index
        // r.x in [0, L-1), and reconstruct k = i + 1 + r.x.
        RDom r(0, len_param - 1, "r");  // empty when L == 1

        Expr k_abs = ii + 1 + r.x;

        // table[i][k]        -> table_param(k_abs, i)
        // table[k+1][j]      -> table_param(j, k_abs+1)
        diag(i) = max(diag(i),
                      table_param(k_abs, ii) +
                      table_param(jj, k_abs + 1));
    }

    // --------------------------------------------------------------------
    // Schedule for the diagonal kernel:
    //
    //  - compute_root(): 'diag' is realized as a stand-alone kernel.
    //  - split & parallelize over i to exploit multi-core CPU.
    //  - vectorize the inner i loop to exploit SIMD.
    //
    // The reduction over r.x (split index k) is left scalar per lane;
    // across different i, computations are independent and safely
    // parallelized / vectorized.
    // --------------------------------------------------------------------
    Var io("io"), ii("ii");
    const int i_tile = 64;   // tile size along i
    const int vec_width = 8; // reasonable SIMD width for 32-bit types

    diag.compute_root();
    diag.split(i, io, ii, i_tile);
    diag.parallel(io);
    diag.vectorize(ii, vec_width);

    // Apply the same parallel/vector schedule to the update definition.
    diag.update()
        .split(i, io, ii, i_tile)
        .parallel(io)
        .vectorize(ii, vec_width);

    // JIT-compile the per-diagonal pipeline once.
    diag.compile_jit();

    // Time the DP kernel (the L/i loops plus Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Original kernel:
    //
    // for (i = N-1; i >= 0; i--)
    //   for (j = i+1; j < N; j++)
    //     ... updates to table[i][j] ...
    //
    // This is equivalent to a wavefront traversal in increasing
    // subsequence length L = j - i:
    //
    // for (L = 1; L < N; L++)
    //   for (i = 0; i + L < N; i++) {
    //     j = i + L;
    //     ... updates to table[i][j] ...
    //   }
    //
