    // but for each fixed L we compute the entire diagonal with a
    // single call to the Halide Func 'diag'.
    for (int L = 1; L < n; ++L) {
        len_param.set(L);

        int num_i = n - L; // i = 0 .. n-L-1

        // Realize diag(i) for this diagonal.
        Halide::Buffer<num_t> diag_buf(num_i);
        diag.realize(diag_buf);

        // Scatter the results back into the DP table:
        // table[i][j] with j = i + L  -> table(j, i)
        for (int i_val = 0; i_val < num_i; ++i_val) {
            int j_val = i_val + L;
            table(j_val, i_val) = diag_buf(i_val);
